"""Drop malformed minIPs before upload (QSMxT#211, fixed upstream in 9.22.0)."""
from pathlib import Path
import sys

import nibabel as nib
import numpy as np


def projection_source(minip):
    # SWI minIPs project *_swi; SMWI writes desc-paramagnetic/diamagnetic minIPs of *_smwi.
    for suffix in ("_swi.nii", "_smwi.nii"):
        for ext in ("", ".gz"):
            candidate = minip.with_name(minip.name.split("_minIP.nii")[0] + suffix + ext)
            if candidate.exists():
                return candidate
    return None


def minip_problem(minip, source):
    image = nib.load(minip)
    try:
        # Read the complete payload: a header-only load missed this bug.
        np.asanyarray(image.dataobj)
    except Exception as exc:
        return f"payload unreadable ({exc})"
    if source is not None:
        shape = nib.load(source).shape
        if len(image.shape) != 3 or image.shape[:2] != shape[:2] or not 1 <= image.shape[2] <= shape[2]:
            return f"shape {image.shape} is not a slab projection of {source.name} {shape}"
    return None


def check_derivatives(root):
    bad = 0
    for minip in Path(root).glob("sub-*/**/anat/*_minIP.nii*"):
        if not (minip.name.endswith(".nii") or minip.name.endswith(".nii.gz")):
            continue
        problem = minip_problem(minip, projection_source(minip))
        if problem:
            bad += 1
            print(f"WARNING: removing malformed minIP {minip.name}: {problem}", file=sys.stderr)
            minip.unlink()
            minip.with_name(minip.name.removesuffix(".gz").removesuffix(".nii") + ".json").unlink(missing_ok=True)
    return bad


if __name__ == "__main__":
    check_derivatives(sys.argv[1])
