import json, re, sys
from pathlib import Path
bids = Path(sys.argv[1]); deriv = bids / "derivatives" / "qsmxt"
def ents(name):
    return dict(re.findall(r"(?:^|_)(sub|ses|acq|run)-([A-Za-z0-9]+)", name))
src = {}
for pat in ("sub-*/ses-*/anat/*part-phase*.json", "sub-*/anat/*part-phase*.json"):
    for j in bids.glob(pat):
        src.setdefault(tuple(sorted(ents(j.name).items())), j)
patched = 0
for nii in deriv.glob("sub-*/**/anat/*.nii*"):
    if not (nii.name.endswith(".nii") or nii.name.endswith(".nii.gz")): continue
    cj = nii.with_name(nii.name.removesuffix(".gz").removesuffix(".nii") + ".json")
    s = src.get(tuple(sorted(ents(cj.name).items())))
    if s is None:
        print("WARNING: no source phase sidecar for %s" % cj.name, file=sys.stderr); continue
    sd = json.loads(s.read_text()); cd = json.loads(cj.read_text()) if cj.exists() else {}
    for k in ("SeriesNumber", "SeriesDescription"):
        if k in sd and k not in cd: cd[k] = sd[k]
    cj.write_text(json.dumps(cd, indent=2)); patched += 1
print("Backfilled SeriesNumber into %d derivative sidecar(s)" % patched)
